python3 -c "
# Also try seasonally adjusted CES data to compare
import urllib.request, json

# Try CES for total nonfarm seasonally adjusted
req = urllib.request.Request(
    'https://api.bls.gov/publicAPI/v2/timeseries/data/CES0000000001?startyear=2004&endyear=2006',
    headers={'User-Agent': 'Mozilla/5.0'}
)
try:
    with urllib.request.urlopen(req, timeout=15) as resp:
        data = json.loads(resp.read())
        results = data['Results']['series'][0]['data']
        month_map = {'M01':1,'M02':2,'M03':3,'M04':4,'M05':5,'M06':6}
        sa = {}
        for r in results:
            if r['period'] in month_map:
                sa[(r['year'], month_map[r['period']])] = float(r['value'])
        print('Seasonally Adjusted:')
        for yr in [2004, 2005, 2006]:
            chg = sa[(yr,6)] - sa[(yr,3)]
            monthly = chg/3
            print(f'{yr}: Jun({sa[(yr,6)]}) - Mar({sa[(yr,3)]}) = {chg}; /3 = {monthly}')
except Exception as e:
    print(f'Error: {e}')
"

python3 -c "
import urllib.request, json

req = urllib.request.Request(
    'https://api.bls.gov/publicAPI/v2/timeseries/data/CES0000000001?startyear=2004&endyear=2006',
    headers={'User-Agent': 'Mozilla/5.0'}
)
try:
    with urllib.request.urlopen(req, timeout=15) as resp:
        data = json.loads(resp.read())
        results = data['Results']['series'][0]['data']
        month_map = {'M01':1,'M02':2,'M03':3,'M04':4,'M05':5,'M06':6}
        sa = {}
        for r in results:
            p = r['period']
            if p in month_map:
                key = (r['year'], month_map[p])
                sa[key] = float(r['value'])
        print('Seasonally Adjusted CES0000000001:')
        for yr in [2004, 2005, 2006]:
            m3 = sa.get((yr,3), 'N/A')
            m6 = sa.get((yr,6), 'N/A')
            chg = m6 - m3 if m3 != 'N/A' else 'N/A'
            monthly = chg/3 if chg != 'N/A' else 'N/A'
            print(f'{yr}: Mar={m3}, Jun={m6}, chg={chg}, monthly={monthly}')
except Exception as e:
    print(f'Error: {e}')
"

